CREATE TABLE "MaintenanceAsset" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "kind" TEXT NOT NULL, "deviceId" TEXT, "nodeId" TEXT, "manufacturer" TEXT, "model" TEXT, "installedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastServicedAt" DATETIME, "serviceIntervalDays" INTEGER, "serviceIntervalHours" REAL, "expectedLifeHours" REAL, "runtimeHours" REAL NOT NULL DEFAULT 0, "healthScore" REAL NOT NULL DEFAULT 100, "status" TEXT NOT NULL DEFAULT 'HEALTHY', "notes" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "MaintenanceEvent" ("id" TEXT NOT NULL PRIMARY KEY, "assetId" TEXT NOT NULL, "type" TEXT NOT NULL, "notes" TEXT, "runtimeHours" REAL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" DATETIME);
CREATE TABLE "WaterTank" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "nodeId" TEXT NOT NULL, "capacityLitres" REAL NOT NULL, "currentLevelPct" REAL NOT NULL DEFAULT 0, "lowLevelPct" REAL NOT NULL DEFAULT 15, "highLevelPct" REAL NOT NULL DEFAULT 95, "pumpNodeId" TEXT, "autoPump" BOOLEAN NOT NULL DEFAULT false, "status" TEXT NOT NULL DEFAULT 'UNKNOWN', "lastSeenAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "WaterReading" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "tankId" TEXT NOT NULL, "levelPct" REAL NOT NULL, "flowLitresMinute" REAL, "pumpRunning" BOOLEAN NOT NULL DEFAULT false, "leakDetected" BOOLEAN NOT NULL DEFAULT false, "timestamp" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "MaintenanceAsset_status_idx" ON "MaintenanceAsset"("status");
CREATE INDEX "MaintenanceAsset_nodeId_idx" ON "MaintenanceAsset"("nodeId");
CREATE INDEX "MaintenanceEvent_assetId_createdAt_idx" ON "MaintenanceEvent"("assetId", "createdAt");
CREATE UNIQUE INDEX "WaterTank_nodeId_key" ON "WaterTank"("nodeId");
CREATE INDEX "WaterReading_tankId_timestamp_idx" ON "WaterReading"("tankId", "timestamp");
